import{z as l,x as s,o as e,c as d,q as i,j as r,D as a,d as B,s as n,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"仿真校准：让模型对上数据","description":"","frontmatter":{"title":"仿真校准：让模型对上数据","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-simulation-calibration.md","filePath":"quant/obd-simulation-calibration.md","lastUpdated":1791063341000}'),u={name:"quant/obd-simulation-calibration.md"};function p(C,E,D,F,m,h){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=i('<h1 id="仿真校准-让模型对上数据" tabindex="-1">仿真校准：让模型对上数据 <a class="header-anchor" href="#仿真校准-让模型对上数据" aria-label="Permalink to &quot;仿真校准：让模型对上数据&quot;">​</a></h1><div class="epigraph"><p>仿真器不产生数据里没有的信息，只把参数的含义展开成路径；校准问的不是「像不像」，是「对下游要紧的那组统计，像不像」。</p><footer>—— 据 Huang, Lehalle and Rosenbaum, JASA, 2015；Bouchaud 等, Trades, Quotes and Prices, 2018 整理</footer></div><p><a href="/quant/obd-eventstudy-micro">上一课</a>的自然实验难得，更日常的回路是仿真：让生成器对上数据，再在生成的世界里问「如果会怎样」。主干已写过 <a href="/quant/queue-reactive">queue-reactive 的仿真</a>、<a href="/quant/abides-simulation">多代理市场仿真 ABIDES</a> 与<a href="/quant/simulator-impact-bias">仿真器的冲击偏差</a>；本课把校准当方法讲：分层对什么、拿什么验证、错在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>仿真器的地位常被摆错成两极：当成比回测更真的世界（它不产生新信息），或当成无用玩具（它恰恰是唯一能做干预实验的世界——放入执行算法，簿会反过来响应）。校准的真问题：模型空间与统计清单都无限长，不可能全对；必须分层规定「对上什么」，按任务规定「放弃什么」。第一课的统计清单在这里升格为校准目标，校准好坏最终体现在下游任务的偏差上——<a href="/quant/simulator-impact-bias">仿真器的冲击偏差</a>就是生效判据。</p><p><span class="marginnote">术语翻译：校准就是「给模型的旋钮找到让输出对上数据的位置」——先固定要对照的统计清单，再调参数，让仿真算出的同一组统计落进容差。没有清单的调参不叫校准，叫把曲线画好看。</span></p><h3 id="校准的层级" tabindex="-1">校准的层级 <a class="header-anchor" href="#校准的层级" aria-label="Permalink to &quot;校准的层级&quot;">​</a></h3><p>层级从低到高：边际统计（点差与深度分布、成交强度、撤成比）→ 联合统计（量价互相关、<a href="/quant/ofi-toxicity">OFI 的 \\(\\beta\\)</a>、冲击函数）→ 动力学（深度自相关、传播核、波动聚集）。低层错了会传染高层：强度定错，核怎么调都对不上动力学——第一课「先状态后自激」的次序在校准上的重演。</p><p><span class="marginnote">校准报告的固定三行：对上了哪些统计、放弃了哪些、参数冗余诊断（哪几组参数对同一统计不可分辨）。没有「放弃」一行的仿真报告默认宣称对上了一切——经验上从不成立，也最容易在下一季度数据上现形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程五步。风格化清单：按目标市场与体制列出要匹配的统计与容差——清单先于代码，否则校准退化成「跑通」。生成器选择：队列级的 QR、点过程级的 Hawkes、代理级的 ABIDES，按问题层级选；代理模型多出的自由度每个都要付校准代价。分步估计：先强度（暴露时间口径），后自激核，再价格规则，每步残差进下一步。参数辨识：不同参数对同一统计冗余时锁定或正则，否则策略结论建在没有唯一解的参数沟里。验证：样本外重跑统计清单；开环诊断与闭环干预分开；任务检验——执行仿真核对实现冲击对<a href="/quant/square-root-impact-law">冲击律</a>的偏差，做市仿真核对毒性响应的方向与量级。</p>',11)),(e(),r(o,null,{default:a(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20SF%5B%22%E9%A3%8E%E6%A0%BC%E5%8C%96%E4%BA%8B%E5%AE%9E%E6%B8%85%E5%8D%95%20%2B%20%E5%AE%B9%E5%B7%AE%22%5D%0A%20%20SF%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E5%99%A8%EF%BC%9AQR%20%2F%20Hawkes%20%2F%20%E4%BB%A3%E7%90%86%22%5D%0A%20%20GEN%20--%3E%20STEP%5B%22%E5%88%86%E6%AD%A5%E6%A0%A1%E5%87%86%EF%BC%9A%E5%BC%BA%E5%BA%A6%E2%86%92%E6%A0%B8%E2%86%92%E4%BB%B7%E6%A0%BC%E8%A7%84%E5%88%99%22%5D%0A%20%20STEP%20--%3E%20IDE%7B%22%E5%8F%82%E6%95%B0%E5%8F%AF%E8%BE%A8%E8%AF%86%EF%BC%9F%22%7D%0A%20%20IDE%20--%3E%7C%E5%90%A6%7C%20REG%5B%22%E9%94%81%E5%AE%9A%2F%E6%AD%A3%E5%88%99%EF%BC%8C%E8%AE%B0%E5%BD%95%E5%86%97%E4%BD%99%22%5D%0A%20%20IDE%20--%3E%7C%E6%98%AF%7C%20VAL%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E9%AA%8C%E8%AF%81%20%2B%20%E5%BC%80%E7%8E%AF%2F%E9%97%AD%E7%8E%AF%E5%88%86%E5%BC%80%22%5D%0A%20%20REG%20--%3E%20VAL%0A%20%20VAL%20--%3E%20TASK%5B%22%E4%BB%BB%E5%8A%A1%E6%A3%80%E9%AA%8C%EF%BC%9A%E6%89%A7%E8%A1%8C%E5%86%B2%E5%87%BB%E5%81%8F%E5%B7%AE%2F%E6%AF%92%E6%80%A7%E5%93%8D%E5%BA%94%22%5D%0A%20%20TASK%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20GEN%0A%20%20TASK%20--%3E%7C%E8%BF%87%7C%20USE%5B%22%E5%B9%B2%E9%A2%84%E5%AE%9E%E9%AA%8C%E4%B8%8E%E7%AD%96%E7%95%A5%E6%B5%8B%E8%AF%95%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"分层的机制：低层统计是高层的生成条件——强度决定什么事件发生，事件流决定上层一切分布与相关，校准必须自底向上；跳层匹配会让上层拟合吸收低层错误，参数从此失去解释。任务加权的机制：全统计对齐不可能，权重唯一合法来源是下游任务——执行研究里冲击函数与深度自相关的一阶矩重要过点差尾部；做市研究里毒性响应量级权重最高。开环与闭环的差别在反身性：开环里市场不理你，闭环里你的订单改写状态，合格参数在闭环里仍可能偏差——这不是校准失败，是两个问题。",-1)),E[5]||(E[5]=A("p",null,"开环与闭环到底差在哪一步、为什么合格参数也会偏，对照着看最清楚：",-1)),(e(),r(o,null,{default:a(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20OL%5B%22%E5%BC%80%E7%8E%AF%3A%E5%B8%82%E5%9C%BA%E4%B8%8D%E7%90%86%E4%BD%A0%22%5D%0A%20%20%20%20O1%5B%22%E7%94%9F%E6%88%90%E5%99%A8%E6%8C%89%E5%8E%86%E5%8F%B2%E5%8F%82%E6%95%B0%E8%B7%91%22%5D%20--%3E%20O2%5B%22%E6%94%BE%E5%85%A5%E6%89%A7%E8%A1%8C%E7%AE%97%E6%B3%95%3A%E7%B0%BF%E6%97%A0%E5%93%8D%E5%BA%94%22%5D%0A%20%20%20%20O2%20--%3E%20O3%5B%22%E7%BB%9F%E8%AE%A1%E8%AF%8A%E6%96%AD%E6%9C%89%E6%95%88%22%5D%0A%20%20end%0A%20%20subgraph%20CL%5B%22%E9%97%AD%E7%8E%AF%3A%E4%BD%A0%E7%9A%84%E8%AE%A2%E5%8D%95%E6%94%B9%E5%86%99%E7%8A%B6%E6%80%81%22%5D%0A%20%20%20%20C1%5B%22%E7%94%9F%E6%88%90%E5%99%A8%E6%8C%89%E5%8E%86%E5%8F%B2%E5%8F%82%E6%95%B0%E8%B7%91%22%5D%20--%3E%20C2%5B%22%E8%AE%A2%E5%8D%95%E8%BF%9B%E7%B0%BF%3A%E9%98%9F%E5%88%97%2F%E4%BB%B7%E5%B7%AE%E8%A2%AB%E6%94%B9%E5%86%99%22%5D%0A%20%20%20%20C2%20--%3E%20C3%5B%22%E5%BC%BA%E5%BA%A6%E6%8C%89%E6%96%B0%E7%8A%B6%E6%80%81%E9%87%8D%E5%8F%96%22%5D%0A%20%20%20%20C3%20--%3E%20C2%0A%20%20end%0A%20%20OL%20--%3E%7C%22%E5%BC%80%E7%8E%AF%E5%8F%82%E6%95%B0%E7%9B%B4%E6%8E%A5%E6%90%AC%E8%BF%9B%E9%97%AD%E7%8E%AF%22%7C%20WARN%5B%22%E5%90%88%E6%A0%BC%E5%8F%82%E6%95%B0%E4%BB%8D%E5%8F%AF%E8%83%BD%E5%81%8F%E5%B7%AE%3A%E4%BB%BB%E5%8A%A1%E6%A3%80%E9%AA%8C%E5%85%9C%E5%BA%95%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">数字实例：若撤成比被校准得差了 30%，跳层拟合会让价格规则的参数把这个缺口悄悄吸收——表面每项容差都达标，参数早已失去解释；任务一换（从执行换到做市），偏差立刻现形。这就是「先强度后核再价格规则」的次序换来的东西。</span></p><p>错法：只对均值（第一课说过，均值对齐最廉价）；校准与验证窗口同源；开环参数直接用于闭环策略测试；隐藏量缺席导致低估冲击、高估打穿；用一次「看起来像」的路径图代替统计验收。</p><p><span class="marginnote">常见误区：初学者容易拿「仿真跑出来的路径长得像真数据」当验证通过。验证对象是统计清单与下游任务偏差，不是某条路径的视觉相似——一条「看起来像」的路径完全可以由错误的参数生成，换一天种子就露馅。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>仿真不外推机制：换制度后的世界没有校准数据，只能给旧机制参数下的猜测，必须标注。代理层的行为假设不可检验：每个智能体的规则都是未校准的自由度，结论只能落在被校准的统计上。校准有样本期烙印：体制变了要重估，参数不是资产。产出永远是条件句——「若世界仍这样运转，则策略如此」——把条件句读成保证，是方法单元所有课的共同边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>仿真器是模型的展开器：价值在干预实验，代价是不产生新信息。</li><li>校准分层：边际 → 联合 → 动力学；自底向上，低层错误会传染高层。</li><li>权重来自下游任务：执行看冲击偏差，做市看毒性响应；没有任务的校准没有权重。</li><li>制度变迁与代理层假设是硬边界：产出是条件句，不是保证。</li><li>出处：Huang, Lehalle and Rosenbaum, <em>JASA</em>, 2015；Byrd, Hybinette and Balch, <em>ABIDES</em>；风格化事实图谱见 Bouchaud 等, <em>Trades, Quotes and Prices</em>, 2018。</li></ul>',7))])}const f=l(u,[["render",p]]);export{b as __pageData,f as default};
